import{_ as t,H as i,f as s,i as a}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"05 | 如何使用FFmpeg与OBS进行直播推流？","description":"","frontmatter":{},"headers":[{"level":2,"title":"FFmpeg 推流","slug":"ffmpeg-推流","link":"#ffmpeg-推流","children":[{"level":3,"title":"命令行参数","slug":"命令行参数","link":"#命令行参数","children":[]}]},{"level":2,"title":"带界面的推流神器 OBS","slug":"带界面的推流神器-obs","link":"#带界面的推流神器-obs","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"快手·音视频技术入门课/05｜如何使用FFmpeg与OBS进行直播推流？.md","filePath":"快手·音视频技术入门课/05｜如何使用FFmpeg与OBS进行直播推流？.md","lastUpdated":1795556509000}'),E={name:"快手·音视频技术入门课/05｜如何使用FFmpeg与OBS进行直播推流？.md"};function n(p,e,A,r,o,g){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_05-如何使用ffmpeg与obs进行直播推流" tabindex="-1">05 | 如何使用FFmpeg与OBS进行直播推流？ <a class="header-anchor" href="#_05-如何使用ffmpeg与obs进行直播推流" aria-label="Permalink to &quot;05 | 如何使用FFmpeg与OBS进行直播推流？&quot;">​</a></h1><p>你好，我是刘歧。</p><p>前面四节课，我们介绍了音视频与直播相关的基础知识，那么接下来我们就要进入实战阶段了。学完这个部分，音视频处理的常用工具怎么用，你就能心中有数了。</p><p>前面我们虽然了解了什么是直播，直播服务器可以用到哪些开源项目。但直播推流到底怎么实现并没有详细展开，所以这节课我们重点讲讲怎么基于 FFmpeg 推直播流。如果你的业务场景用 FFmpeg 不太方便，我还提供了另一个方法——桌面工具 OBS 推流。相信学完之后，你就能轻松搞定推流。</p><p>首先，我们做直播推流的前提是要有直播服务器接收直播流，所以需要我们自己建设一个流媒体服务器。我们可以根据上一节课提到的开源直播服务器的官方文档部署直播服务器，也可以挖掘自己当前使用的直播服务平台的服务器接收直播流。为了方便演示，我使用快手的直播云服务来接收我推的直播流。界面如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/1.png" alt=""></a></p><h2 id="ffmpeg-推流" tabindex="-1">FFmpeg 推流 <a class="header-anchor" href="#ffmpeg-推流" aria-label="Permalink to &quot;FFmpeg 推流&quot;">​</a></h2><p>通常，推流服务器的管理界面会提供一个收流的 RTMP 服务器地址，还会提供一个直播流的流名称，也叫串流密钥。例如推流的 RTMP 服务器地址是 rtmp://publish.x.com/live，串流密钥是 stream，那么最后组成的推流地址就是 rtmp://publish.x.com/live/stream。</p><p>如果使用 FFmpeg 推 RTMP 流的话，我们需要使用的输出格式为 FLV，那么 FFmpeg 的输入就是 -f flv rtmp://publish.x.com/live/stream。为了便于理解，我们自己模拟一个直播画面，然后推 RTMP 直播流，下面是完整的命令行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ffmpeg -re -f lavfi -i testsrc=s=1280x720:r=25 -pix_fmt yuv420p -vcodec libx264 -</span></span></code></pre></div><p>这条命令行理解起来比较简单，FFmpeg 分两大部分，一部分是输入部分，也就是 -i 与 -i 的参数以及它之前的部分，另一部分就是 -i 与 -i 参数后面的部分，为输出部分。仔细划分一下，这条命令行的输入部分是 -re -f lavfi -i testsrc=s=1280x720:r=25，输出部分是 -pix_fmtyuv420p -vcodec libx264 -f flv rtmp://publish.x.com/live/stream。</p><h3 id="命令行参数" tabindex="-1">命令行参数 <a class="header-anchor" href="#命令行参数" aria-label="Permalink to &quot;命令行参数&quot;">​</a></h3><p>输入部分的意思是使用 FFmpeg 的 lavfi 输入格式，也可以说输入的是 lavfi 设备。输入内容是testsrc，这个 testsrc 是输入 lavfi 格式的内容，lavfi 的格式有很多内容，这些内容不是既有的内容，也不是某个文件，而是 FFmpeg 通过 filter 自己创建出来的。除了 testsrc，还可以创建testsrc2、color、yuvall 等图像内容（更多可创建的内容你可以查看FFmpeg 官方文档）。输入的图像是 25fps，也就是每秒钟会得到 25 帧图像，图像的宽是 1280 像素，高是 720 像素。</p><p>如果你足够细心的话，就会发现我还没有讲 -re 这个参数。它其实是控制获得图像频率的参数，用来控制输入包的读取速度，比如我们规定一秒钟输入 25 帧，它会把速度控制在 25帧。因为在 FFmpeg 中数据是以最快的速度读完的，一般在高配的机器上读取速度会非常快。我们用 FFmpeg 自主生成的数据来模拟直播，就需要用 -re 来控制一下速度。但如果我们是读取摄像头还有 RTSP 等直播协议输入的数据，就可以不控制，因为对方输出也是控制频率的。</p><p>输出部分的意思是先把读取的图像像素点的颜色格式转成 yuv420p 格式，关于 yuv420p 格式，我们在前面的课程中是讲过的，这里为什么使用 yuv420p 呢？因为 yuv420p 在视频图像格式中是兼容性最好的，使用起来会比较稳定。</p><p>接下来编码器部分使用的视频编码器为 libx264。libx264 是一个第三方编码器，这里我们需要注意的是 libx264 的 FFmpeg 需要使用自由软件基金会的通用公共协议的 License，也就是常说的 GPL 协议。作为开源软件发行版使用问题不大，如果商用的话可能需要考虑法律风险。</p><p>我们继续看输出部分，-f flv 规定我们输出的封装格式为 FLV，用 -f 指定封装格式以后，输出文件的文件名其实也不会有作用，因为 FFmpeg 会强制输出 -f 指定的输出格式。最后输出的文件是一个 RTMP 协议特征字符开头的 URL，所以最终会将 FLV 格式的内容输出到 FFmpegRTMP 协议内容中。</p><p>到这里，使用 FFmpeg 推流到 RTMP 服务器就可以执行了。我们点开快手，到我们自己的直播间看一下效果，从图中可以看到直播已经开始了，testsrc 的画面已经出来了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/2.png" alt=""></a></p><p>有些人觉得安装 FFmpeg 太麻烦了，并且使用命令行也比较繁琐，记不住参数。刚入门的时候使用 FFmpeg 可能确实有些麻烦，会觉得参数太多。其实用着用着找到窍门后，你就会发现 FFmpeg 参数并不多，尤其是我们常用的能力部分，模块化做得很好，不同的编码器都有自己的参数可以配置，如果我们集中精力只关注我们自己使用的模块部分，参数并不多也很容易记住。</p><p>当然有些人可能想要采集自己的摄像头、桌面等外设，这些通过 FFmpeg 的 -devices 参数可以得到相关的设备信息。通过FFmpeg 的设备相关的操作文档指引信息，我们也可以自己用FFmpeg 获得摄像头、桌面等外设图像，通过编码推流到直播服务器上。支持的外设比较多，这里就不展开说了，具体内容你可以参考文档自己挖掘一下。</p><h2 id="带界面的推流神器-obs" tabindex="-1">带界面的推流神器 OBS <a class="header-anchor" href="#带界面的推流神器-obs" aria-label="Permalink to &quot;带界面的推流神器 OBS&quot;">​</a></h2><p>如果你确实觉得 FFmpeg 太难、太麻烦，还有一种方式也能帮助你完成推流。那就是使用界面直播推流神器 OBS，这种工具不用命令行，也可以帮你轻松搞定推流。</p><p>OBS 是个桌面应用程序，首先我们需要从 OBS 官方网站下载 OBS 并安装上，安装后打开的界面比较直观。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/3.png" alt=""></a></p><p>OBS 的功能非常强大，这里我们主要介绍抓取本地窗口的场景。首先我们基于场景添加一个来源，来源可以选择窗口采集。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/4.png" alt=""></a></p><p>然后选择一个窗口，比如我正在本地用播放器播放一个 MP4 的视频，我可以通过 OBS 抓取这个播放 MP4 视频的播放器窗口，我们预计将这个播放器正在播放的内容以直播的方式推流到 RTMP 服务器上。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/5.png" alt=""></a></p><p>然后我们设置一下推流和编码器，点设置按钮。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/6.png" alt=""></a></p><p>进入设置窗口后选推流选项，填入 RTMP 服务器地址，推流密钥。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/7.png" alt=""></a></p><p>为了让推流更流畅，我们还需要进入视频选项里面，设置一下视频的编码参数。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/8.png" alt=""></a></p><p>主要是分辨率和帧率，需要我们稍微调整一下，比如我的播放器播放的视频是 720p，那我就可以选择 720p 对应的分辨率，关于分辨率我们在第一节课已经介绍过了，你可以一边回顾一边操作。</p><p>接下来我们设置一下音频编码参数。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/9.png" alt=""></a></p><p>音频编码我们可以根据自己的需要进行设置，比如是否采集桌面声音，是否采集麦克风声音等，我们这里选择默认的麦克风输入声音即可。</p><p>当然，如果我们推流的 PC 机有 GPU 卡，或者我们想直接用 CPU 软编码的话，可以进入高级设置项设置详细参数。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/10.png" alt=""></a></p><p>对应的可以设置的参数还是挺多的，比如我这里默认用的是 x264 编码器，那么可以设置码率是否为 CBR，CBR 主要是恒定码率，也就是在画面和视频图像运动场景比较复杂的时候，画质会显得模糊一些，如果用 VBR 的动态码率的话，在画质方面会根据图像运动场景等因素存储更多的参考帧相关的信息，码率会动态地拉升。</p><p>之后就需要设置关键帧间隔，这里我设置的 1 其实不太合理，一般我们设置 2 到 5 秒钟比较合理。关键帧间隔设置得合理的话，可以确保直播延迟低的同时画质更高，这个部分我们完全可以根据自己的考核标准操作。再往下看就是 H.264 编码标准里面的设置，例如快速编码，编码的 profile 设置，是否用低延迟模式等。</p><p>如果这些参数设置得不尽兴的话，了解了 x264 的更多详细参数后，你也可以自己选填更细节的参数。当然，如果想用 GPU 编码的话，也可以自由选择，比如我是苹果电脑，那么我可以选择使用 videotoolbox 进行视频编码，这样也可以节省一些我的 CPU 资源，电脑的风扇也会相对安静一些，编码性能大多数情况下会比 CPU 编码要高很多。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/11.png" alt=""></a></p><p>推流之后，我们就能在直播间里看到自己的直播流内容了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%8A%80%E6%9C%AF%E5%85%A5%E9%97%A8%E8%AF%BE/images/05/12.png" alt=""></a></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>到这里，我们可以在零基础的情况下做直播推流，推一些我们自己的内容到直播服务器上面了。无论是使用 FFmpeg 还是 OBS，都能够很好地作为推流客户端进行推流，使用 FFmpeg推流的话一条命令行就可以搞定。如果你不喜欢用鼠标点来点去的话，推荐你使用 FFmpeg推流；而用 OBS 的话，不需要下载安装 FFmpeg，不需要点开终端自己输入各种参数，也不用特意去记这些参数就能轻松搞定推流，深度挖掘的话，甚至还可以实现导播等功能。</p><p>更多 OBS 的高级功能和黑科技，还是需要我们自己耐心地去一点点挖掘。在这里我通过简单的介绍引领你入门，目的是让你具备基础的直播推流能力。但师父领进门，修行在个人，还是需要你自己动手实际操作起来，相信你会有不小的收获。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>通过刚刚的操作，我们推流成功了，而且也能在播放器端看到推流成功后的直播流了，那么我们怎么确认这个直播流是不是我们设置好的 1280x720 的分辨率，帧率是不是 25fps 呢？期待在评论区看到你的答案，也欢迎你把这节课分享给需要的朋友，我们下节课再见！</p>',52)])])}const F=t(E,[["render",n]]);export{B as __pageData,F as default};
